import React, { useEffect, useMemo, useRef, useState } from 'react';
import {
  Elements,
  PaymentElement,
  useElements,
  useStripe,
} from '@stripe/react-stripe-js';
import { loadStripe, type Stripe } from '@stripe/stripe-js';
import {
  ArrowLeft,
  ArrowRight,
  Check,
  CreditCard,
  Loader2,
  Lock,
  Mail,
  ShieldCheck,
  UserRound,
} from 'lucide-react';
import { motion } from 'motion/react';
import { useNavigate, useParams } from 'react-router-dom';
import { LocalizedPrice } from '../components/store/LocalizedPrice';
import {
  BusinessSubscriptionCheckoutError,
  createBusinessSubscriptionCheckout,
} from '../lib/businessSubscriptionCheckout';
import { invokeApiRunner, supabase } from '../lib/supabase';
import { routes } from '../routing/routes';

type PublicBusiness = {
  id: string;
  name: string;
  slug: string;
  logo_url?: string | null;
};

type PublicPlan = {
  id: string;
  business_id: string;
  name: string;
  description?: string | null;
  price: number;
  currency?: string | null;
  interval: string;
  features?: string[] | null;
};

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const intervalLabel = (interval: string) => {
  switch (interval.toLowerCase()) {
    case 'day':
    case 'daily':
      return 'day';
    case 'week':
    case 'weekly':
      return 'week';
    case 'year':
    case 'yearly':
    case 'annual':
      return 'year';
    default:
      return 'month';
  }
};

const friendlyCheckoutError = (error: unknown) => {
  const code = error instanceof BusinessSubscriptionCheckoutError
    ? String(error.code || '').toUpperCase()
    : '';
  if (['SELLER_PAYMENTS_DISABLED', 'STRIPE_ACCOUNT_INACCESSIBLE'].includes(code)) {
    return 'This business cannot accept payments right now. Please contact the business.';
  }
  if (code === 'STRIPE_ONBOARDING_INCOMPLETE') {
    return 'This business must finish Stripe verification before it can accept subscriptions.';
  }
  if (code === 'RATE_LIMITED') {
    return 'Too many checkout attempts. Wait a few minutes and try again.';
  }
  return error instanceof Error && error.message
    ? error.message
    : 'Secure subscription checkout is temporarily unavailable.';
};

const SubscriptionPaymentForm = ({
  checkoutId,
  returnPath,
  onBack,
}: {
  checkoutId: string;
  returnPath: string;
  onBack: () => void;
}) => {
  const stripe = useStripe();
  const elements = useElements();
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState('');

  const submitPayment = async (event: React.FormEvent) => {
    event.preventDefault();
    if (!stripe || !elements || submitting) return;

    setError('');
    setSubmitting(true);
    try {
      const submission = await elements.submit();
      if (submission.error) {
        setError(submission.error.message || 'Check your payment details.');
        return;
      }

      const returnUrl = new URL('/payment-success', window.location.origin);
      returnUrl.searchParams.set('source', 'business-subscription');
      returnUrl.searchParams.set('checkout_id', checkoutId);
      returnUrl.searchParams.set('status', 'processing');
      returnUrl.searchParams.set('return_to', returnPath);

      const confirmation = await stripe.confirmPayment({
        elements,
        confirmParams: { return_url: returnUrl.toString() },
      });
      if (confirmation.error) {
        setError(confirmation.error.message || 'The payment could not be completed.');
      }
    } catch (paymentError) {
      setError(paymentError instanceof Error ? paymentError.message : 'The payment could not be completed.');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <form onSubmit={submitPayment}>
      <div className="mb-7 flex items-center justify-between">
        <div>
          <p className="text-xs font-black uppercase tracking-[0.22em] text-white/35">Step 2 of 2</p>
          <h2 className="mt-2 text-2xl font-black tracking-tight">Choose how to pay</h2>
        </div>
        <button
          type="button"
          onClick={onBack}
          className="rounded-full border border-white/10 px-4 py-2 text-xs font-bold text-white/60 transition hover:bg-white/[0.06] hover:text-white"
        >
          Edit details
        </button>
      </div>

      <div className="rounded-2xl border border-white/10 bg-white p-4 sm:p-5">
        <PaymentElement
          options={{
            layout: { type: 'accordion', defaultCollapsed: false, radios: true, spacedAccordionItems: true },
          }}
        />
      </div>

      {error && (
        <div role="alert" className="mt-5 rounded-2xl border border-red-400/20 bg-red-400/10 px-4 py-3 text-sm leading-6 text-red-100">
          {error}
        </div>
      )}

      <button
        type="submit"
        disabled={!stripe || !elements || submitting}
        className="mt-6 flex min-h-14 w-full items-center justify-center gap-2 rounded-2xl bg-white px-6 text-sm font-black text-black transition hover:bg-white/90 disabled:cursor-not-allowed disabled:opacity-50"
      >
        {submitting ? (
          <>
            <Loader2 className="h-4 w-4 animate-spin" />
            Confirming securely
          </>
        ) : (
          <>
            Subscribe securely
            <ArrowRight className="h-4 w-4" />
          </>
        )}
      </button>
      <p className="mt-4 flex items-center justify-center gap-2 text-center text-xs leading-5 text-white/35">
        <Lock className="h-3.5 w-3.5" />
        Payment details are securely handled by Stripe.
      </p>
    </form>
  );
};

export const BusinessPlanCheckout = () => {
  const navigate = useNavigate();
  const { businessSlug = '', planId = '' } = useParams();
  const [business, setBusiness] = useState<PublicBusiness | null>(null);
  const [plan, setPlan] = useState<PublicPlan | null>(null);
  const [loading, setLoading] = useState(true);
  const [pageError, setPageError] = useState('');
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [creating, setCreating] = useState(false);
  const [clientSecret, setClientSecret] = useState('');
  const [checkoutId, setCheckoutId] = useState('');
  const [stripePromise, setStripePromise] = useState<Promise<Stripe | null> | null>(null);
  const requestId = useRef(crypto.randomUUID());

  const returnPath = useMemo(
    () => routes.businessPlanCheckout({ businessSlug, planId }),
    [businessSlug, planId],
  );

  useEffect(() => {
    let cancelled = false;
    const loadCheckout = async () => {
      setLoading(true);
      setPageError('');
      try {
        const { data: businessData, error: businessError } = await supabase
          .from('businesses')
          .select('id,name,slug,logo_url')
          .eq('slug', businessSlug)
          .maybeSingle();
        if (businessError) throw businessError;
        if (!businessData) throw new Error('Business not found.');

        const { data: planData, error: planError } = await supabase
          .from('plans')
          .select('id,business_id,name,description,price,currency,interval,features')
          .eq('id', planId)
          .eq('business_id', businessData.id)
          .eq('is_active', true)
          .maybeSingle();
        if (planError) throw planError;
        if (!planData) throw new Error('This subscription plan is no longer available.');

        const { data: authData } = await supabase.auth.getUser();
        if (cancelled) return;
        setBusiness(businessData as PublicBusiness);
        setPlan(planData as PublicPlan);
        if (authData.user?.email) setEmail(authData.user.email);
        const fullName = String(authData.user?.user_metadata?.full_name || '').trim();
        if (fullName) setName(fullName);
      } catch (error) {
        if (!cancelled) setPageError(error instanceof Error ? error.message : 'Checkout could not be loaded.');
      } finally {
        if (!cancelled) setLoading(false);
      }
    };
    void loadCheckout();
    return () => {
      cancelled = true;
    };
  }, [businessSlug, planId]);

  const continueToPayment = async (event: React.FormEvent) => {
    event.preventDefault();
    setPageError('');
    if (name.trim().length < 2) {
      setPageError('Enter your full name.');
      return;
    }
    if (!EMAIL_PATTERN.test(email.trim())) {
      setPageError('Enter a valid email address.');
      return;
    }
    if (!plan) return;

    setCreating(true);
    try {
      const [config, checkout] = await Promise.all([
        invokeApiRunner('stripe-config', {}, 1, 800),
        createBusinessSubscriptionCheckout({
          planId: plan.id,
          requestId: requestId.current,
          email: email.trim(),
          name: name.trim(),
        }),
      ]);
      const publishableKey = typeof config?.publishableKey === 'string'
        ? config.publishableKey.trim()
        : '';
      if (!publishableKey) throw new Error('Secure payments are temporarily unavailable.');

      if (!checkout.clientSecret) {
        navigate(`/payment-success?source=business-subscription&checkout_id=${encodeURIComponent(checkout.checkoutId)}&status=processing&return_to=${encodeURIComponent(returnPath)}`);
        return;
      }

      setCheckoutId(checkout.checkoutId);
      setClientSecret(checkout.clientSecret);
      setStripePromise(loadStripe(publishableKey, { stripeAccount: checkout.stripeAccountId }));
    } catch (error) {
      setPageError(friendlyCheckoutError(error));
    } finally {
      setCreating(false);
    }
  };

  if (loading) {
    return (
      <div className="flex min-h-[100dvh] items-center justify-center bg-[#070707] text-white">
        <Loader2 className="h-7 w-7 animate-spin text-white/60" />
      </div>
    );
  }

  if (!business || !plan) {
    return (
      <div className="flex min-h-[100dvh] items-center justify-center bg-[#070707] px-5 text-white">
        <div className="max-w-md text-center">
          <h1 className="text-3xl font-black">Checkout unavailable</h1>
          <p className="mt-3 leading-7 text-white/50">{pageError || 'This subscription plan is not available.'}</p>
          <button onClick={() => navigate(-1)} className="mt-7 rounded-2xl bg-white px-6 py-3 font-black text-black">
            Go back
          </button>
        </div>
      </div>
    );
  }

  const billingInterval = intervalLabel(plan.interval);
  const currency = plan.currency || 'EUR';

  return (
    <div className="relative min-h-[100dvh] overflow-hidden bg-[#070707] text-white">
      <div className="pointer-events-none absolute -left-40 -top-48 h-[520px] w-[520px] rounded-full bg-blue-500/15 blur-[150px]" />
      <div className="pointer-events-none absolute -bottom-60 right-0 h-[560px] w-[560px] rounded-full bg-violet-500/10 blur-[160px]" />

      <header className="relative z-10 mx-auto flex w-full max-w-7xl items-center justify-between px-5 py-5 sm:px-8">
        <button
          type="button"
          onClick={() => navigate(`/${encodeURIComponent(business.slug)}`)}
          className="inline-flex items-center gap-2 text-sm font-bold text-white/55 transition hover:text-white"
        >
          <ArrowLeft className="h-4 w-4" />
          Back to {business.name}
        </button>
        <div className="text-base font-black tracking-tight">Wersee</div>
      </header>

      <main className="relative z-10 mx-auto grid min-h-[calc(100dvh-76px)] w-full max-w-7xl items-center gap-10 px-5 py-8 sm:px-8 lg:grid-cols-[minmax(0,0.9fr)_minmax(480px,1.1fr)] lg:gap-16 lg:py-12">
        <section className="max-w-xl">
          <div className="mb-8 flex items-center gap-3">
            {business.logo_url ? (
              <img src={business.logo_url} alt="" className="h-11 w-11 rounded-2xl border border-white/10 object-cover" />
            ) : (
              <div className="flex h-11 w-11 items-center justify-center rounded-2xl border border-white/10 bg-white/[0.06] text-sm font-black">
                {business.name.slice(0, 1).toUpperCase()}
              </div>
            )}
            <div>
              <p className="text-xs font-bold uppercase tracking-[0.2em] text-white/35">Subscription by</p>
              <p className="mt-1 font-bold text-white/80">{business.name}</p>
            </div>
          </div>

          <p className="text-xs font-black uppercase tracking-[0.24em] text-blue-300">Recurring plan</p>
          <h1 className="mt-4 text-5xl font-black tracking-[-0.05em] sm:text-6xl">{plan.name}</h1>
          {plan.description && <p className="mt-5 max-w-lg text-base leading-7 text-white/50">{plan.description}</p>}

          <div className="mt-8 flex items-end gap-2">
            <LocalizedPrice
              amount={plan.price}
              baseCurrency={currency}
              className="text-4xl font-black tracking-tight text-white sm:text-5xl"
              showOriginal={false}
            />
            <span className="pb-1 text-sm font-bold text-white/35">/ {billingInterval}</span>
          </div>

          {(plan.features || []).length > 0 && (
            <ul className="mt-9 grid gap-3 sm:grid-cols-2">
              {(plan.features || []).map((feature) => (
                <li key={feature} className="flex items-start gap-3 text-sm leading-6 text-white/65">
                  <span className="mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-white/10">
                    <Check className="h-3 w-3" />
                  </span>
                  {feature}
                </li>
              ))}
            </ul>
          )}

          <div className="mt-10 grid grid-cols-2 gap-3 text-xs text-white/40">
            <div className="flex items-center gap-2 rounded-2xl border border-white/10 bg-white/[0.025] p-4">
              <ShieldCheck className="h-4 w-4 text-emerald-300" />
              Stripe secured
            </div>
            <div className="flex items-center gap-2 rounded-2xl border border-white/10 bg-white/[0.025] p-4">
              <CreditCard className="h-4 w-4 text-blue-300" />
              Real payment methods
            </div>
          </div>
        </section>

        <motion.section
          initial={{ opacity: 0, y: 18 }}
          animate={{ opacity: 1, y: 0 }}
          className="rounded-[32px] border border-white/10 bg-[#111]/95 p-5 shadow-2xl shadow-black/40 backdrop-blur sm:p-8"
        >
          {clientSecret && stripePromise && checkoutId ? (
            <Elements
              stripe={stripePromise}
              options={{
                clientSecret,
                appearance: {
                  theme: 'stripe',
                  variables: {
                    colorPrimary: '#111111',
                    colorText: '#111111',
                    colorDanger: '#dc2626',
                    borderRadius: '12px',
                    fontFamily: 'Inter, ui-sans-serif, system-ui, sans-serif',
                  },
                },
              }}
            >
              <SubscriptionPaymentForm
                checkoutId={checkoutId}
                returnPath={returnPath}
                onBack={() => {
                  setClientSecret('');
                  setCheckoutId('');
                  setStripePromise(null);
                }}
              />
            </Elements>
          ) : (
            <form onSubmit={continueToPayment}>
              <p className="text-xs font-black uppercase tracking-[0.22em] text-white/35">Step 1 of 2</p>
              <h2 className="mt-2 text-2xl font-black tracking-tight">Your details</h2>
              <p className="mt-2 text-sm leading-6 text-white/45">We use these details for your subscription and receipt.</p>

              <div className="mt-7 space-y-4">
                <label className="block">
                  <span className="mb-2 block text-xs font-bold text-white/55">Full name</span>
                  <span className="relative block">
                    <UserRound className="absolute left-4 top-1/2 h-4 w-4 -translate-y-1/2 text-white/30" />
                    <input
                      value={name}
                      onChange={(event) => setName(event.target.value)}
                      autoComplete="name"
                      placeholder="Your full name"
                      className="min-h-14 w-full rounded-2xl border border-white/10 bg-white/[0.045] pl-11 pr-4 text-sm text-white outline-none transition placeholder:text-white/25 focus:border-white/30 focus:bg-white/[0.065]"
                    />
                  </span>
                </label>
                <label className="block">
                  <span className="mb-2 block text-xs font-bold text-white/55">Email address</span>
                  <span className="relative block">
                    <Mail className="absolute left-4 top-1/2 h-4 w-4 -translate-y-1/2 text-white/30" />
                    <input
                      type="email"
                      value={email}
                      onChange={(event) => setEmail(event.target.value)}
                      autoComplete="email"
                      placeholder="you@example.com"
                      className="min-h-14 w-full rounded-2xl border border-white/10 bg-white/[0.045] pl-11 pr-4 text-sm text-white outline-none transition placeholder:text-white/25 focus:border-white/30 focus:bg-white/[0.065]"
                    />
                  </span>
                </label>
              </div>

              {pageError && (
                <div role="alert" className="mt-5 rounded-2xl border border-red-400/20 bg-red-400/10 px-4 py-3 text-sm leading-6 text-red-100">
                  {pageError}
                </div>
              )}

              <div className="mt-6 rounded-2xl border border-white/10 bg-white/[0.025] p-4">
                <div className="flex items-center justify-between gap-4">
                  <div>
                    <p className="text-sm font-bold">{plan.name}</p>
                    <p className="mt-1 text-xs text-white/35">Renews every {billingInterval} until cancelled</p>
                  </div>
                  <LocalizedPrice amount={plan.price} baseCurrency={currency} className="font-black text-white" showOriginal={false} />
                </div>
              </div>

              <button
                type="submit"
                disabled={creating}
                className="mt-6 flex min-h-14 w-full items-center justify-center gap-2 rounded-2xl bg-white px-6 text-sm font-black text-black transition hover:bg-white/90 disabled:cursor-not-allowed disabled:opacity-50"
              >
                {creating ? (
                  <>
                    <Loader2 className="h-4 w-4 animate-spin" />
                    Preparing secure payment
                  </>
                ) : (
                  <>
                    Continue to payment
                    <ArrowRight className="h-4 w-4" />
                  </>
                )}
              </button>
              <p className="mt-4 text-center text-[11px] leading-5 text-white/30">
                By continuing, you agree to recurring billing at the interval shown. You can cancel future renewals through billing.wersee.com.
              </p>
            </form>
          )}
        </motion.section>
      </main>
    </div>
  );
};
